'use strict';
const $=id=>document.getElementById(id),M=WageModel;
const controls=[['progress','AI progress / quarter',0,10,.5,' pts','sliders'],['opportunities','New opportunities / quarter',0,6,.5,'','sliders'],['payoff','New-work payoff multiplier',.2,3,.1,'×','sliders'],['demand','Demand elasticity',0,3,.25,'','sliders'],['delay','Learning delay',1,8,1,' qtrs','advanced'],['error','Initial belief error',0,100,5,'%','advanced'],['review','Staffing review interval',1,4,1,' qtrs','advanced'],['transition','Cost per hire / exit',0,50,5,'k','advanced'],['aiCost','AI cost per replaced hour',0,60,5,' $','advanced'],['compression','Potential wage pressure',0,50,5,'%','advanced'],['feedback','Learning feedback strength',0,3,.25,'','advanced']];
for(const [id,label,min,max,step,suffix,parent] of controls){$(parent).insertAdjacentHTML('beforeend',`<label for="${id}">${label}<output id="${id}Value">${M.defaults[id]}${suffix}</output></label><input type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${M.defaults[id]}">`);$(id).oninput=()=>{$(id+'Value').textContent=$(id).value+suffix;dirty();};}
const helps={baseline:'Capability stays at zero; no new assignments. A stability check, not a prediction.',automation:'AI advances through existing tasks. New assignments are deliberately excluded.',replenishment:'New assignments appear but are protected from AI indefinitely. A favorable boundary case for human work.',pursuit:'New work appears. Task-specific AI starts behind it and can catch up.',feedback:'Human hours on a new assignment also accelerate AI capability for that assignment.'};
let result,repeated=null,comparison=null,timer=null;
const cash=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const short=n=>Math.abs(n)>=1e6?'$'+(n/1e6).toFixed(2)+'m':'$'+(n/1000).toFixed(0)+'k';
function dirty(){$('dirty').textContent='Assumptions changed. Run experiment to update the results.';}
function params(){const p={...M.defaults,mode:$('mode').value,seed:Math.max(0,Math.min(4294967295,Math.floor(Number($('seed').value)||0)))};for(const [id]of controls)p[id]=Number($(id).value);return p;}
function modeHelp(){$('modeHelp').textContent=helps[$('mode').value];dirty();}
$('mode').onchange=modeHelp;$('seed').oninput=dirty;
function stop(){clearInterval(timer);timer=null;$('play').textContent='Play timeline';}
function run(){stop();result=M.simulate(params());repeated=null;comparison=null;$('quarter').value=0;$('ensemble').textContent='Run repeated experiments to see the range of final payrolls.';$('comparison').innerHTML='';$('dirty').textContent='Showing '+M.modes[result.params.mode]+' · seed '+result.params.seed;render();}
$('run').onclick=run;$('reset').onclick=()=>{for(const [id,,,,suffix]of controls){$(id).value=M.defaults[id];$(id+'Value').textContent=M.defaults[id]+suffix;}$('mode').value=M.defaults.mode;$('seed').value=M.defaults.seed;modeHelp();run();};
$('quarter').oninput=render;$('measure').onchange=renderChart;$('filter').onchange=renderEvents;
$('play').onclick=()=>{if(timer){stop();return;}if(Number($('quarter').value)===20)$('quarter').value=0;$('play').textContent='Pause';timer=setInterval(()=>{$('quarter').value=Number($('quarter').value)+1;render();if(Number($('quarter').value)>=20)stop();},950);};
function render(){const s=result.history[Number($('quarter').value)];$('quarterTitle').textContent=s.q===0?'Starting position':`Year ${Math.ceil(s.q/4)} · Quarter ${((s.q-1)%4)+1} (Q${s.q})`;
$('metrics').innerHTML=[[short(s.payroll),'Annual payroll'],[s.n,'Paid roles'],[short(s.wage),'Annual wage per role'],[(s.payroll/1000000*100).toFixed(0)+'%','Starting payroll retained']].map(([v,l])=>`<div class="metric"><strong>${v}</strong><span>${l}</span></div>`).join('');
const activeBricks=Math.round(s.wage/1000),estPer=s.n?s.supportedBricks/s.n:0,trialPer=s.n?s.trialBricks/s.n:0;
$('towers').innerHTML=s.roles.map((r,i)=>{let b='';const active=r.active?activeBricks:0,estCount=Math.floor(estPer)+(i<s.supportedBricks%s.n?1:0),usedCount=estCount+Math.floor(trialPer)+(i>=s.n-s.trialBricks%s.n?1:0);for(let j=99;j>=0;j--){let type=j>=active?'removed':j<estCount?'est':j<usedCount?'trial':'idle';b+=`<i class="brick ${type}"></i>`;}return `<button class="tower" data-role="${i}" aria-label="Inspect role ${r.id}: ${r.active?cash(s.wage):'removed'}"><span class="stack">${b}</span><span class="tower-label">ROLE ${String(r.id).padStart(2,'0')}</span><span class="tower-value">${r.active?short(s.wage):'Removed'}</span></button>`;}).join('');
document.querySelectorAll('.tower').forEach(b=>b.onclick=()=>{const r=s.roles[Number(b.dataset.role)];$('brickDetail').textContent=`Role ${r.id}: ${r.active?activeBricks+' paid bricks ('+cash(s.wage)+' annually).':'No wages currently paid.'} ${r.last}`;});
$('brickDetail').textContent=s.changes.length?s.changes[0].message:'Select a tower to inspect its latest wage decision. Each small brick is $1,000 of annual wages.';
$('flow').innerHTML=`<span><b>${s.supportedBricks}</b> established</span><span><b>${s.trialBricks}</b> experimental</span><span><b>${s.releasedBricks}</b> paid, unassigned</span><span><b>${cash(s.cumulative)}</b> cumulative operating profit</span>`;
$('taskTable').innerHTML='<table><thead><tr><th>Core task</th><th>Starting effort</th><th>Delivery</th><th>Human hours / qtr</th></tr></thead><tbody>'+s.tasks.map(t=>`<tr><td>${t.name}</td><td>${(t.share*100).toFixed(0)}%</td><td class="status">${t.ai?'AI':'Human'}</td><td>${Math.round(t.hours).toLocaleString()}</td></tr>`).join('')+'</tbody></table>';
$('newCount').textContent=`New assignments · ${s.projects.filter(x=>!x.closed).length} open / ${s.projects.length} admitted`;
$('projects').innerHTML=s.projects.length?'<table><thead><tr><th>Assignment</th><th>Status</th><th>Believed benefit / qtr</th><th>True potential / qtr</th><th>Hours delivered</th></tr></thead><tbody>'+s.projects.map(t=>`<tr><td>${t.name}</td><td>${t.closed?'Stopped':t.ai?'AI + checking':t.age<result.params.delay?'Experimental':'Established'}</td><td>${cash(t.estimate)}</td><td>${cash(t.value)}</td><td>${Math.round(t.allocated)}</td></tr>`).join('')+'</tbody></table><p class="hint">True potential is visible to you as the experimenter. Management uses its belief. Benefits shown assume full delivery; unstaffed assignments generate no revenue.</p>':'<p class="hint">No assignments admitted yet.</p>';
renderChart();renderEvents();}
function renderEvents(){const q=Number($('quarter').value),f=$('filter').value,es=result.events.filter(e=>e.q<=q&&(f==='all'||e.type===f)).slice().reverse();$('events').innerHTML=es.length?es.map(e=>`<div class="event"><time>Q${e.q}</time><div><b>${e.type}</b><p>${e.message}</p></div></div>`).join(''):'<p class="hint">No matching decisions up to this quarter. Move the timeline forward to follow the experiment.</p>';}
function svgChart(series,key,band=false){
 const w=850,h=270,l=80,r=20,t=20,b=40,values=series.flatMap(x=>band?[x.p10,x.p90]:[x[key]]),lo=Math.min(0,...values),hi=Math.max(1,...values)*1.08,span=hi-lo;
 const x=q=>l+q/20*(w-l-r),y=v=>h-b-(v-lo)/span*(h-t-b),fmt=v=>['n','hours','output'].includes(key)?Math.round(v*10)/10:short(v);
 let s=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${band?'Payroll range over 100 seeds':$('measure').selectedOptions[0].text} over 20 quarters">`;
 for(let i=0;i<5;i++){const v=lo+span*i/4;s+=`<line x1="${l}" y1="${y(v)}" x2="${w-r}" y2="${y(v)}" stroke="#e2e9ec"/><text x="${l-10}" y="${y(v)+4}" text-anchor="end" fill="#536670" font-size="13">${fmt(v)}</text>`;}
 for(let q=0;q<=20;q+=4)s+=`<text x="${x(q)}" y="${h-12}" text-anchor="middle" fill="#536670" font-size="13">${q===0?'Start':'Year '+q/4}</text>`;
 if(band)s+=`<polygon points="${series.map(a=>x(a.q)+','+y(a.p90)).concat([...series].reverse().map(a=>x(a.q)+','+y(a.p10))).join(' ')}" fill="#cee6e0"/>`;
 s+=`<polyline points="${series.map(a=>x(a.q)+','+y(a[band?'median':key])).join(' ')}" fill="none" stroke="#127b70" stroke-width="3"/>`;
 if(!band){const q=Number($('quarter').value),v=series[q][key];s+=`<line x1="${x(q)}" x2="${x(q)}" y1="${t}" y2="${h-b}" stroke="#8ba7af" stroke-dasharray="4 4"/><circle cx="${x(q)}" cy="${y(v)}" r="5" fill="#127b70"/>`;}
 return s+'</svg>';
}
function renderChart(){const key=$('measure').value,s=result.history[Number($('quarter').value)],v=s[key];$('chart').innerHTML=svgChart(result.history,key)+`<p class="chart-caption">Selected quarter: <b>${['n','hours','output'].includes(key)?v.toLocaleString('en-US',{maximumFractionDigits:2}):cash(v)}</b>. End of year five: <b>${['n','hours','output'].includes(key)?result.history[20][key].toLocaleString('en-US',{maximumFractionDigits:2}):cash(result.history[20][key])}</b>.</p>`;}
$('repeat').onclick=async()=>{const b=$('repeat');b.disabled=true;b.textContent='Running…';await new Promise(r=>setTimeout(r,30));try{repeated=M.ensemble(result.params,100);const last=repeated.summary[20];$('ensemble').innerHTML=`<p class="result-big">Year-five median payroll: ${cash(last.median)}</p><p class="hint">10th–90th percentile: ${cash(last.p10)}–${cash(last.p90)}. ${repeated.below} of 100 runs finish below the starting $1m payroll. This is a frequency under these rules, not a forecast probability.</p>`+svgChart(repeated.summary,'payroll',true);}finally{b.disabled=false;b.textContent='Run 100 seeds';}};
$('compare').onclick=async()=>{const b=$('compare');b.disabled=true;b.textContent='Comparing…';await new Promise(r=>setTimeout(r,30));try{comparison=Object.entries(M.modes).map(([mode,name])=>({name,mode,...M.ensemble({...result.params,mode},30)}));$('comparison').innerHTML='<div class="table-wrap"><table><thead><tr><th>Experiment</th><th>Median final payroll</th><th>10th–90th percentile</th></tr></thead><tbody>'+comparison.map(c=>{const s=c.summary[20];return `<tr><td>${c.name}</td><td>${cash(s.median)}</td><td>${short(s.p10)}–${short(s.p90)}</td></tr>`;}).join('')+'</tbody></table></div><p class="hint">Thirty matched seeds per experiment; all other controls held at the last-run values. Constant AI and automation-only deliberately exclude new work. Protected new work deliberately cannot be automated.</p>';}finally{b.disabled=false;b.textContent='Compare all five experiments · 30 seeds each';}};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({result,repeated,comparison},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='wage-towers-'+result.params.mode+'-seed-'+result.params.seed+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
modeHelp();run();
